begin;
create extension if not exists pgtap with schema extensions;
select plan(26);
insert into auth.users(id,email,raw_user_meta_data) values
 ('10000000-0000-0000-0000-000000000001','person-review-one@example.test','{}'),
 ('10000000-0000-0000-0000-000000000002','person-review-two@example.test','{}');
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
select lives_ok($$select public.save_person_review(3223,5,'first','[{"media_type":"movie","tmdb_id":1726}]'::jsonb)$$,'owner creates rating and reference');
select is((select count(*) from public.person_review_works),1::bigint,'reference inserted');
select is((select count(*) from public.person_reviews where person_tmdb_id=3223),1::bigint,'one review');
select throws_ok($$select public.save_person_review(3223,3,'duplicate','[]'::jsonb)$$,'40001',null,'concurrent creation rejected');
select throws_ok($$select public.save_person_review(3223,2,'stale','[]'::jsonb,'2000-01-01T00:00:00Z')$$,'40001',null,'stale update rejected');
select is((select rating from public.person_reviews where person_tmdb_id=3223),5,'failed update preserves rating');
select throws_ok($$select public.save_person_review(3223,4,'bad','[{"media_type":"movie","tmdb_id":1726},{"media_type":"movie","tmdb_id":1726}]'::jsonb,(select updated_at from public.person_reviews where person_tmdb_id=3223))$$,'22023',null,'duplicate references rejected');
select is((select count(*) from public.person_review_works),1::bigint,'invalid request preserves existing references');
select throws_ok($$select public.save_person_review(3223,4,'bad',(select jsonb_agg(jsonb_build_object('media_type','movie','tmdb_id',n)) from generate_series(1,11) n),(select updated_at from public.person_reviews where person_tmdb_id=3223))$$,'22023',null,'more than ten references rejected');
select throws_ok($$select public.save_person_review(3223,4,'bad','[{"media_type":"person","tmdb_id":1}]'::jsonb,(select updated_at from public.person_reviews where person_tmdb_id=3223))$$,'22023',null,'invalid type rejected');
select throws_ok($$select public.save_person_review(3223,6,'bad','[]'::jsonb,(select updated_at from public.person_reviews where person_tmdb_id=3223))$$,'22023',null,'invalid rating rejected');
select lives_ok($$select public.save_person_review(3223,3,null,'[{"media_type":"tv","tmdb_id":1434}]'::jsonb,(select updated_at from public.person_reviews where person_tmdb_id=3223))$$,'owner updates atomically');
select is((select rating from public.person_reviews where person_tmdb_id=3223),3,'updated rating visible');
select is((select media_type from public.person_review_works limit 1),'tv','references replaced');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
select throws_ok($$insert into public.person_review_works(review_id,media_type,tmdb_id,position) select id,'movie',99,2 from public.person_reviews where person_tmdb_id=3223$$,'42501',null,'cannot insert into another users review');
select throws_ok($$insert into public.person_reviews(user_id,person_tmdb_id,rating) values ('10000000-0000-0000-0000-000000000001',7,5)$$,'42501',null,'cannot forge owner');
select lives_ok($$select public.save_person_review(3223,5,null,'[]'::jsonb)$$,'second user can rate same person');
update public.person_review_works set tmdb_id=88 where review_id=(select id from public.person_reviews where user_id='10000000-0000-0000-0000-000000000001' and person_tmdb_id=3223);
select is((select tmdb_id from public.person_review_works limit 1),1434::bigint,'another user cannot update references');
select is((select average_rating from public.person_rating_stats(999999)),null::numeric,'empty aggregate is null');
select is((select review_count from public.person_rating_stats(3223)),2::bigint,'aggregate counts all users');
select is((select average_rating from public.person_rating_stats(3223)),4::numeric,'aggregate averages all users');
delete from public.person_reviews where user_id='10000000-0000-0000-0000-000000000002' and person_tmdb_id=3223;
select is((select average_rating from public.person_rating_stats(3223)),3::numeric,'aggregate changes on deletion');
set local role anon;
select set_config('request.jwt.claim.sub','',true);
select is((select count(*) from public.person_reviews where person_tmdb_id=3223),1::bigint,'anonymous can read reviews');
select throws_ok($$select public.save_person_review(3223,5,null,'[]'::jsonb)$$,'42501',null,'anonymous cannot call write RPC');
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
delete from public.person_reviews where person_tmdb_id=3223 and user_id='10000000-0000-0000-0000-000000000001';
select is((select count(*) from public.person_review_works),0::bigint,'delete cascades references');
select is((select review_count from public.person_rating_stats(3223)),0::bigint,'aggregate count reflects last deletion');
select * from finish();
rollback;
